class TestPerformanceTestPageViewPanel(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_web_driver):
        self.tested_page_view_panel = PerformanceTestPageViewPanel()

    def test_start_pusch_test(self):
        expected_local_cell = 'NRCELL-1337'
        expected_frc_index = 'Some Nice Index'
        expected_do_rate = 'some bitrate'
        expected_do_type = 'some serial'
        expected_rep_time_int = 6
        expected_beam_id = 500
        expected_ru_mode = 'some ru mode'
        expected_physical_cell_id = 20
        expected_bb_selector = 2
        expected_prb_offset = 111
        expected_timeout = 23

        self.tested_page_view_panel._setup_common_params = mock.Mock()
        self.tested_page_view_panel.select_element_from_dropdown_list_by_text_and_click = mock.Mock()
        self.tested_page_view_panel.insert_text_to_enable_element = mock.Mock()
        self.tested_page_view_panel.click_enabled_element = mock.Mock()

        self.tested_page_view_panel.\
            start_pusch_test(local_cell=expected_local_cell, frc_index=expected_frc_index, do_rate=expected_do_rate,
                             do_type=expected_do_type, rep_time_int=expected_rep_time_int, beam_id=expected_beam_id,
                             ru_mode=expected_ru_mode, physical_cell_id=expected_physical_cell_id,
                             bb_selector=expected_bb_selector, prb_offset=expected_prb_offset, timeout=expected_timeout)

        self.tested_page_view_panel._setup_common_params.\
            assert_called_once_with(expected_local_cell, expected_beam_id, expected_ru_mode, expected_rep_time_int,
                                    expected_physical_cell_id, expected_timeout, test_type='PUSCH')

        self.tested_page_view_panel.select_element_from_dropdown_list_by_text_and_click.assert_has_calls(
            [call(expected_do_type,
                  (By.XPATH, '//div[contains(text(), "Digital output type:")]/parent::*//button'),
                  (By.XPATH, '//div[contains(text(), "Digital output type:")]/parent::*//ul//li'),
                  expected_timeout),
             call(expected_do_rate,
                  (By.XPATH, '//div[contains(text(), "Digital output rate:")]/parent::*//button'),
                  (By.XPATH, '//div[contains(text(), "Digital output rate:")]/parent::*//ul//li'),
                  expected_timeout),
             call(expected_frc_index,
                  (By.XPATH, '//div[contains(text(), "FRC index:")]/parent::*//button'),
                  (By.XPATH, '//div[contains(text(), "FRC index:")]/parent::*//ul//li'),
                  expected_timeout)])

        self.tested_page_view_panel.insert_text_to_enable_element.assert_has_calls(
            [call((By.XPATH, '//div[contains(text(), "BB selector:")]/parent::*//input'),
                  str(expected_bb_selector),
                  expected_timeout),
             call((By.XPATH, '//div[contains(text(), "PRB offset:")]/parent::*//input'),
                  str(expected_prb_offset),
                  expected_timeout)])

        self.tested_page_view_panel.click_enabled_element.\
            assert_called_once_with((By.XPATH, '//button[contains(text(), "Start Test")]'), expected_timeout)

